def pct(x):
    return f"{100*x:.1f}%"


def f3(x):
    return f"{x:.3f}"


def set_cell_text(cell, text, bold=False, size=9):
    cell.text = ""
    p = cell.paragraphs[0]
    r = p.add_run(str(text))
    r.bold = bold
    r.font.name = "Times New Roman"
    r.font.size = Pt(size)
    cell.vertical_alignment = WD_CELL_VERTICAL_ALIGNMENT.CENTER


def shade_cell(cell, fill):
    tcPr = cell._tc.get_or_add_tcPr()
    shd = tcPr.find(qn("w:shd"))
    if shd is None:
        shd = OxmlElement("w:shd")
        tcPr.append(shd)
    shd.set(qn("w:fill"), fill)


def set_repeat_table_header(row):
    trPr = row._tr.get_or_add_trPr()
    tblHeader = OxmlElement("w:tblHeader")
    tblHeader.set(qn("w:val"), "true")
    trPr.append(tblHeader)


def add_field(paragraph, field):
    run = paragraph.add_run()
    fldChar1 = OxmlElement("w:fldChar")
    fldChar1.set(qn("w:fldCharType"), "begin")
    instrText = OxmlElement("w:instrText")
    instrText.set(qn("xml:space"), "preserve")
    instrText.text = field
    fldChar2 = OxmlElement("w:fldChar")
    fldChar2.set(qn("w:fldCharType"), "end")
    run._r.append(fldChar1)
    run._r.append(instrText)
    run._r.append(fldChar2)


def add_page_number(section):
    footer = section.footer
    p = footer.paragraphs[0]
    p.alignment = WD_ALIGN_PARAGRAPH.CENTER
    r = p.add_run("Page ")
    r.font.name = "Times New Roman"; r.font.size = Pt(9)
    add_field(p, "PAGE")


def add_table(doc, headers, rows, widths=None, caption=None):
    if caption:
        p = doc.add_paragraph()
        p.alignment = WD_ALIGN_PARAGRAPH.CENTER
        r = p.add_run(caption)
        r.bold = True; r.font.name = "Times New Roman"; r.font.size = Pt(10)
    table = doc.add_table(rows=1, cols=len(headers))
    table.style = "Table Grid"
    table.alignment = WD_TABLE_ALIGNMENT.CENTER
    hdr = table.rows[0]
    set_repeat_table_header(hdr)
    for i, h in enumerate(headers):
        set_cell_text(hdr.cells[i], h, bold=True, size=8.5)
        shade_cell(hdr.cells[i], "D9EAF7")
    for row in rows:
        cells = table.add_row().cells
        for i, val in enumerate(row):
            set_cell_text(cells[i], val, size=8.5)
    if widths:
        for row in table.rows:
            for i, width in enumerate(widths):
                row.cells[i].width = Inches(width)
    doc.add_paragraph()
    return table


def add_bullets(doc, items, level=0):
    for item in items:
        p = doc.add_paragraph(style="List Bullet" if level == 0 else "List Bullet 2")
        p.paragraph_format.space_after = Pt(3)
        p.add_run(item)


def add_numbered(doc, items):
    for item in items:
        p = doc.add_paragraph(style="List Number")
        p.paragraph_format.space_after = Pt(3)
        p.add_run(item)


def add_unit(doc, heading, paragraphs=None, bullets=None, table=None, figure=None, figure_caption=None, level=2):
    doc.add_heading(heading, level=level)
    for text in paragraphs or []:
        p = doc.add_paragraph(text)
        p.paragraph_format.first_line_indent = Cm(0.75)
    if bullets:
        add_bullets(doc, bullets)
    if table:
        headers, rows, widths, caption = table
        add_table(doc, headers, rows, widths, caption)
    if figure and Path(figure).exists():
        p = doc.add_paragraph(); p.alignment = WD_ALIGN_PARAGRAPH.CENTER
        p.add_run().add_picture(str(figure), width=Inches(6.25))
        if figure_caption:
            cp = doc.add_paragraph(figure_caption); cp.alignment = WD_ALIGN_PARAGRAPH.CENTER
    doc.add_page_break()


def set_document_styles(doc):
    styles = doc.styles
    normal = styles["Normal"]
    normal.font.name = "Times New Roman"
    normal.font.size = Pt(12)
    normal.paragraph_format.line_spacing = 1.5
    normal.paragraph_format.space_after = Pt(6)
    for name, size, color in [("Heading 1", 16, "1F4E79"), ("Heading 2", 14, "1F4E79"), ("Heading 3", 12, "2F5597")]:
        s = styles[name]
        s.font.name = "Times New Roman"; s.font.size = Pt(size); s.font.bold = True; s.font.color.rgb = __import__('docx').shared.RGBColor.from_string(color)
        s.paragraph_format.space_before = Pt(10); s.paragraph_format.space_after = Pt(6)
    for section in doc.sections:
        section.top_margin = Cm(2.5); section.bottom_margin = Cm(2.5)
        section.left_margin = Cm(3.0); section.right_margin = Cm(2.5)
        add_page_number(section)


def literature_unit(title, study1, study2, synthesis):
    return [
        f"{study1} {synthesis}",
        f"{study2} Together, these studies are relevant to the present thesis because they show how clinical prediction can be strengthened by combining multiple measurements while also demonstrating the danger of treating a single high-performing model as sufficient evidence. The present work therefore separates discrimination from calibration, documents the unit of splitting, and reports the restrictions imposed by the available cohorts."
    ]


