# Chapter 4 results: 15 units
clinical_table = (['Model','AUROC','AUPRC','Brier','Accuracy','Balanced acc.','F1'], [
 ['Elastic-net logistic', f3(clinical_metrics['elastic_net_logistic']['oof_metrics']['auroc']), f3(clinical_metrics['elastic_net_logistic']['oof_metrics']['auprc']), f3(clinical_metrics['elastic_net_logistic']['oof_metrics']['brier']), pct(clinical_metrics['elastic_net_logistic']['oof_metrics']['accuracy']), pct(clinical_metrics['elastic_net_logistic']['oof_metrics']['balanced_accuracy']), f3(clinical_metrics['elastic_net_logistic']['oof_metrics']['f1'])],
 ['XGBoost', f3(clinical_metrics['xgboost']['oof_metrics']['auroc']), f3(clinical_metrics['xgboost']['oof_metrics']['auprc']), f3(clinical_metrics['xgboost']['oof_metrics']['brier']), pct(clinical_metrics['xgboost']['oof_metrics']['accuracy']), pct(clinical_metrics['xgboost']['oof_metrics']['balanced_accuracy']), f3(clinical_metrics['xgboost']['oof_metrics']['f1'])],
 ['EBM', f3(clinical_metrics['ebm']['oof_metrics']['auroc']), f3(clinical_metrics['ebm']['oof_metrics']['auprc']), f3(clinical_metrics['ebm']['oof_metrics']['brier']), pct(clinical_metrics['ebm']['oof_metrics']['accuracy']), pct(clinical_metrics['ebm']['oof_metrics']['balanced_accuracy']), f3(clinical_metrics['ebm']['oof_metrics']['f1'])]
], [1.4,.7,.7,.7,.9,1.0,.7], 'Table 4.1. Out-of-fold binary clinical-cohort performance using the full clinical marker set.')
add_unit(doc, "4.1 Cohort description", ["Dataset A contained 56 cats: 25 Healthy and 31 CKD cats. The CKD group consisted of 3 stage-1, 14 stage-2, 9 stage-3 and 5 stage-4 observations. Dataset B contained 195 urine observations from 41 animal IDs in the downloaded spreadsheet: 97 Healthy, 54 CaOx and 44 CKD observations. The effective animal-level sample was therefore much smaller than the row count.", "The two class distributions are not directly comparable. Dataset A labels represent a clinical staging classification, while Dataset B labels represent conditions in a urine-metabolomics experiment. Their results are presented as separate analyses, and no pooled score is calculated.", ""], table=(['Cohort','Rows/observations','Animals/IDs','Classes','Primary task'], [['Clinical', '56', '56 patient IDs', 'Healthy 25; CKD 31', 'Binary and exploratory stage classification'], ['Urine metabolomics', '195', '41 IDs in file', 'Healthy 97; CaOx 54; CKD 44', 'Grouped three-class classification']], [1.2,1.1,1.1,1.7,2.2], 'Table 4.0. Frozen cohort summary.'))
add_unit(doc, "4.2 Full-marker clinical classification", ["The full-marker clinical analysis produced high out-of-fold discrimination for all three model families. Elastic-net logistic regression achieved AUROC 0.992 and AUPRC 0.994; XGBoost achieved AUROC 0.982 and AUPRC 0.986; EBM achieved AUROC 0.990 and AUPRC 0.992. EBM produced the lowest Brier score at 0.039, followed by logistic regression at 0.059 and XGBoost at 0.070.", "These results should not be interpreted as evidence of a deployable clinical classifier. USG, BUN and creatinine dominated the XGBoost SHAP ranking, and those variables are close to the clinical rules used to describe CKD. The high score is therefore a useful demonstration of separability in the published cohort, but it also demonstrates circularity risk.", ""], table=clinical_table, figure=str(FIG/'clinical_roc.png'), figure_caption="Figure 4.1. Clinical cohort out-of-fold ROC curves. The apparent discrimination is interpreted together with the circularity ablation.")
add_unit(doc, "4.3 Clinical explanation rankings", ["The XGBoost SHAP ranking placed USG first, followed by BUN, creatinine, muscle condition score, age and bicarbonate. EBM gave a similar ordering for USG and BUN but assigned more distributed importance to muscle condition, age, cholesterol, total protein and missingness indicators. Logistic coefficients also placed USG, BUN, muscle condition, total protein and age near the top.", "The convergence of models is partly reassuring because the strongest features are clinically plausible. It is also a warning: the strongest features may be strong precisely because the outcome was defined using renal function. The interpretation is therefore descriptive and not causal. The explanation result supports the need for the context-only ablation rather than a simple claim that all models discovered independent biomarkers.", ""], table=(['Rank','XGBoost SHAP feature','EBM-related feature','Interpretive note'], [['1','USG','USG','Renal concentration; close to outcome definition'],['2','BUN','BUN','Renal waste marker; label proximity'],['3','Creatinine','Muscle condition','Renal marker versus physical context'],['4','Muscle condition','Creatinine','Potential confounding by body composition'],['5','Age','Age','Expected demographic association'],['6','Bicarbonate','Cholesterol/TP','Secondary systemic context']], [0.5,1.7,1.5,2.6], 'Table 4.2. Top clinical explanation features.'))
add_unit(doc, "4.4 Context-only clinical ablation", ["When creatinine, BUN, SDMA, phosphorus, USG and proteinuria were excluded, performance fell for every model. Logistic regression achieved AUROC 0.895, XGBoost 0.894 and EBM 0.880. AUPRC remained between 0.910 and 0.913, while balanced accuracy ranged from 0.787 to 0.839. The result indicates that demographic, physical and non-defining laboratory context retains some classification signal, but the full-marker score substantially overstates what the model can do without diagnostic biomarkers.", "The ablation is the most important robustness result in the clinical cohort. It does not transform the study into a causal risk model because the remaining variables may still reflect disease severity, referral patterns or treatment. It does, however, separate a near-rule-reproduction task from a harder contextual classification task.", ""], table=(['Model','AUROC','AUPRC','Brier','Accuracy','Balanced acc.','F1'], [[m.replace('_',' ').title(), f3(v['oof_metrics']['auroc']), f3(v['oof_metrics']['auprc']), f3(v['oof_metrics']['brier']), pct(v['oof_metrics']['accuracy']), pct(v['oof_metrics']['balanced_accuracy']), f3(v['oof_metrics']['f1'])] for m,v in context_metrics.items()], [1.4,.7,.7,.7,.9,1.0,.7], 'Table 4.3. Context-only clinical ablation excluding label-defining renal markers.'), figure=str(FIG/'clinical_ablation_comparison.png'), figure_caption="Figure 4.4. Full-marker versus context-only clinical AUROC." )
add_unit(doc, "4.5 Exploratory clinical stage classification", ["The five-level stage analysis was exploratory because stage 1 contained only three cats. XGBoost produced an out-of-fold macro-AUROC of 0.890, macro AUPRC of 0.692, accuracy of 0.768, balanced accuracy of 0.513 and macro F1 of 0.475. Logistic regression produced macro-AUROC 0.808, macro AUPRC 0.608, accuracy 0.679, balanced accuracy 0.459 and macro F1 0.467.", "The confusion matrix showed that the models separated Healthy and much of stage 2 more readily than they separated stages 3 and 4 or the rare stage-1 cases. This is expected because the class sizes are small and the stage label is ordinal while the models were trained as nominal multiclass classifiers. The result is reported to expose the limitation, not as evidence of reliable automated staging.", ""], table=(['Model','Macro AUROC','Macro AUPRC','Accuracy','Balanced acc.','Macro F1','Multiclass Brier'], [['Elastic-net logistic',f3(stage_metrics['elastic_net_logistic']['oof_metrics']['macro_auroc_ovr']),f3(stage_metrics['elastic_net_logistic']['oof_metrics']['macro_auprc_ovr']),pct(stage_metrics['elastic_net_logistic']['oof_metrics']['accuracy']),pct(stage_metrics['elastic_net_logistic']['oof_metrics']['balanced_accuracy']),f3(stage_metrics['elastic_net_logistic']['oof_metrics']['macro_f1']),f3(stage_metrics['elastic_net_logistic']['oof_metrics']['multiclass_brier'])],['XGBoost',f3(stage_metrics['xgboost']['oof_metrics']['macro_auroc_ovr']),f3(stage_metrics['xgboost']['oof_metrics']['macro_auprc_ovr']),pct(stage_metrics['xgboost']['oof_metrics']['accuracy']),pct(stage_metrics['xgboost']['oof_metrics']['balanced_accuracy']),f3(stage_metrics['xgboost']['oof_metrics']['macro_f1']),f3(stage_metrics['xgboost']['oof_metrics']['multiclass_brier'])]], [1.4,.9,.9,.9,1.0,.9,1.1], 'Table 4.4. Exploratory five-level clinical stage classification.'))
add_unit(doc, "4.6 Clinical local explanations", ["LIME explanations were generated for three deterministic clinical examples using the fitted XGBoost model. The local weights were not treated as population-level evidence. Their purpose was to demonstrate how an individual prediction could be narrated and to show why local explanations need to be read together with the underlying feature values, imputation indicators and disease-definition context.", "A clinically responsible interface would need to show the measurement date, reference interval, missingness state and whether a feature is part of the diagnostic definition. A plot that simply says that USG or BUN was important would be incomplete. The explanation must also disclose that the model may be rediscovering the variables used to assign the CKD category.", ""], figure=str(FIG/'clinical_pr.png'), figure_caption="Figure 4.2. Clinical cohort precision-recall curves for full-marker binary classification.")
add_unit(doc, "4.7 Metabolomics classification performance", ["The metabolomics analysis used five-fold StratifiedGroupKFold, with animal ID as the grouping variable. Logistic regression achieved the highest grouped out-of-fold macro-AUROC at 0.718 and macro AUPRC at 0.535. EBM achieved macro-AUROC 0.699 and XGBoost 0.681. Balanced accuracy was approximately 0.50 for all three models, and macro F1 ranged from 0.495 to 0.500.", "The modest results are more credible than a row-level split would have been because repeated urine observations from one animal were kept together. The confusion matrices showed that Healthy observations were identified more often than CKD and CaOx observations, while the two renal-related conditions were frequently confused. This limits claims about CKD-specific recognition from metabolomics alone.", ""], table=(['Model','Macro AUROC','Macro AUPRC','Accuracy','Balanced acc.','Macro F1','Multiclass Brier'], [[m.replace('_',' ').title(), f3(v['oof_metrics']['macro_auroc_ovr']), f3(v['oof_metrics']['macro_auprc_ovr']), pct(v['oof_metrics']['accuracy']), pct(v['oof_metrics']['balanced_accuracy']), f3(v['oof_metrics']['macro_f1']), f3(v['oof_metrics']['multiclass_brier'])] for m,v in metabolomics_metrics.items()], [1.4,.9,.9,.9,1.0,.9,1.1], 'Table 4.5. Animal-grouped metabolomics performance.'))
add_unit(doc, "4.8 Metabolomics explanations", ["The leading XGBoost SHAP features included 2-methylserine, m-tyramine sulfate, 2'-O-methyluridine, 2-methylcitrate/homocitrate, arabonate/xylonate and pyridoxamine. EBM highlighted m-tyramine sulfate, 2-methylserine, pyridoxamine, 5-methyl-2'-deoxycytidine, glycerophosphoglycerol and 2-methylcitrate/homocitrate. The overlap suggests some explanation convergence, but the metabolite names should not be interpreted as validated feline CKD biomarkers.", "Feature selection frequency showed that several metabolites were selected in all five training folds, including C-glycosyltryptophan, isoputreanine, ribitol, ribonate, choline, glycerophosphoglycerol and related compounds. Five folds are not enough to establish stable biological markers. The correct interpretation is that these features were repeatedly useful under this particular small cohort and feature-selection scheme.", ""], table=(['Rank','XGBoost SHAP feature','EBM feature','Selection frequency example'], [['1','2-methylserine','m-tyramine sulfate','Several leading features selected in 5/5 folds'],['2','m-tyramine sulfate','2-methylserine','Repeated cross-method appearance'],['3',"2'-O-methyluridine",'pyridoxamine','Metabolite-level association, not causation'],['4','2-methylcitrate/homocitrate','5-methyl-2-deoxycytidine','Requires independent validation'],['5','arabonate/xylonate','glycerophosphoglycerol','Potential cohort-specific signal']], [0.5,2.0,1.8,2.2], 'Table 4.6. Leading metabolomics explanation features.'))
add_unit(doc, "4.9 Confusion patterns and class imbalance", ["The metabolomics confusion matrices showed a strong tendency to classify Healthy observations correctly relative to CaOx and CKD. Because the row counts are unequal and repeated observations are clustered, accuracy is not a sufficient summary. Balanced accuracy and macro F1 were therefore included. Their values near 0.50 indicate that the models did not produce reliable separation across all three conditions under animal-level evaluation.", "This finding is informative for the thesis because it prevents an explanation plot from being mistaken for a useful diagnostic system. A model may identify biochemical gradients associated with renal physiology while failing to distinguish clinical categories that are close in disease mechanism or sample context. Future work would need larger animal-level cohorts, harmonised metabolite assays and clinically annotated covariates.", ""], figure=str(FIG/'metabolomics_confusion_matrices.png'), figure_caption="Figure 4.3. Confusion matrices for the three grouped metabolomics classifiers." )
add_unit(doc, "4.10 Feature-selection stability", ["The five grouped training folds repeatedly selected a set of metabolites, but the frequency result should not be overinterpreted. Feature selection is influenced by the small number of animals, correlated metabolites and the published analytical preprocessing. The frequency table is best viewed as a reproducibility diagnostic: it reveals which features survive the chosen folds, not which metabolites are universally predictive.", "The clinical explanation rankings were more interpretable in physiological terms because the variable names corresponded to established laboratory measures. The metabolomics names were mapped from the published legend, but their biological roles, assay robustness and clinical availability were outside the present study. This distinction is central to the thesis's cross-cohort comparison." ] )
add_unit(doc, "4.11 Comparative interpretation across cohorts", ["The clinical cohort showed higher apparent discrimination than the metabolomics cohort, but the tasks differ. Clinical labels and renal biomarkers are tightly connected, whereas the metabolomics task distinguishes three conditions using high-dimensional urine signals. The clinical context-only ablation reduced the gap and showed that the full-marker result was partly a label-reproduction problem.", "The most defensible cross-cohort conclusion is therefore methodological: structured clinical data can look highly separable when defining biomarkers are present, while metabolomics requires animal-level grouping and stronger regularisation. The results do not establish that one modality is clinically superior." ])
add_unit(doc, "4.12 Ablation and sensitivity interpretation", ["The context-only ablation was treated as a sensitivity analysis rather than a replacement endpoint. It removes six markers that are biologically relevant and clinically useful, so performance loss is expected. The purpose is to estimate how much apparent prediction depends on those markers. This is analogous to asking whether a model adds contextual information beyond a near-direct diagnostic measurement.", "The metabolomics analysis did not use a comparable clinical-marker ablation because its feature space is a different assay domain and no common clinical covariates were present. Instead, the primary sensitivity control was grouped splitting and fold-specific feature selection. These controls target the most serious risk in that cohort: repeated-row leakage and high-dimensional overfitting." ])
add_unit(doc, "4.13 Reproducibility outputs", ["The run produced JSON metric files, OOF probability CSV files, feature-importance CSV files, feature-selection frequency files, LIME example outputs and four PNG figures. The source script and frozen manifest are retained in the research folder. These artefacts are part of the thesis evidence chain and should accompany any submission or examiner request.", "The pipeline was rerun after fixing two compatibility and serialisation errors and after adding the clinical circularity ablation and metabolite-name mapping. Only the final successful run is used in the reported tables. This is documented because reproducibility includes the history of corrections, not just the final score." ])
add_unit(doc, "4.14 Results summary", ["The strongest result is not the full-marker AUROC. It is the contrast between full-marker and context-only clinical performance, combined with the modest grouped metabolomics performance. The results show why model reporting must include outcome construction, grouping, ablation and explanation stability. A thesis that reported only the 0.99 clinical AUROC would be technically accurate about the run but scientifically incomplete about what the run means.", "The measured results support a cautious conclusion: interpretable ML can organise and compare signals in public feline renal cohorts, but the evidence is not sufficient for a validated early-detection tool. The next chapter discusses how the results relate to the proposal, the literature and the data-access problem." ])
add_unit(doc, "4.15 Chapter conclusion", ["Chapter 4 reported all primary empirical outputs. The clinical models achieved high performance on the full marker set but lower performance after excluding label-defining renal biomarkers. The stage analysis was exploratory and unstable for rare stages. The grouped metabolomics models showed modest multiclass performance and comparable weaknesses across model families. Explanation methods highlighted plausible but not validated features. These findings are carried forward without embellishment into the discussion." ])

# Chapter 5: 8 units
for h, ps in [
("5.1 Interpretation of the main findings", ["The thesis began with an early-identification proposal and ended with a two-cohort classification study because the required longitudinal data were not available. That change is not a failure of the research process; it is an empirical consequence of data governance. The results show that a smaller, transparent study can still expose important methodological issues, especially circularity and row-level leakage.", "In Dataset A, the difference between full-marker and context-only performance is the central result. Full-marker models almost perfectly separated Healthy and CKD observations because USG, BUN and creatinine carry direct information about the clinical label. Once those variables were removed, performance declined but remained above chance. This suggests that body condition, age, blood pressure and broader physiological context may contain useful signal, but the sample is too small to establish independent predictors." ]),
("5.2 Comparison with the original proposal", ["The proposal's model families remain present: logistic regression, XGBoost, EBM, SHAP and LIME. The proposed data-preparation concepts were retained where appropriate, but the longitudinal rolling features, lead-time calculation and DAP analysis were removed. The title and questions were revised to match the available evidence.", "This is the correct relationship between proposal and thesis. A proposal is a plan under assumptions; a final thesis is an account of what was actually possible, executed and measured. DAP remains in the background and limitations as an unavailable candidate, not as a hidden dataset. Projected numerical values from the proposal were not used." ]),
("5.3 Clinical implications without overclaiming", ["The clinical dataset contains variables that veterinarians already use to interpret renal function. The models therefore demonstrate feasibility of structured classification, not replacement of clinical diagnosis. The context-only result is particularly relevant: if future work seeks added value beyond standard renal markers, it should prospectively define the decision point, outcome horizon and clinical comparator before model fitting.", "No owner-facing or veterinary decision-support claim should be made from this thesis. The appropriate next step would be a controlled, longitudinal, multi-practice cohort with repeated tests, explicit disease-onset definitions and independent validation. Such a project would need ethics and data-governance review." ]),
("5.4 Explainability implications", ["The study supports a layered explanation strategy. EBM provides direct shape functions; SHAP provides model-specific additive attributions for XGBoost; LIME offers local illustrations. None of these alone establishes clinical truth. Explanation quality should be assessed with perturbation, ablation, stability, clinical alignment and, where possible, expert review.", "The metabolomics results demonstrate a practical problem: a model may select chemically named features that are not available in routine practice and whose assay reliability is unknown. An explanation is useful only when the measurement is understood, the feature is not an artefact, and the user knows the limits of the cohort." ]),
("5.5 Limitations", ["The main limitations are small sample size, cross-sectional design of Dataset A, absence of future-onset labels, different tasks across cohorts, possible label-defining predictor leakage, rare stage-1 cases, high-dimensional metabolomics, the 41-versus-42 animal discrepancy, lack of external validation, and no clinician or owner user study. The source studies' sampling frames and analytical protocols were not controlled by this thesis.", "The results are also sensitive to software versions, preprocessing choices and the selected feature-selection threshold. Confidence intervals were not used as a substitute for cohort expansion. The thesis therefore avoids claims of generalisation to all cats, practices or laboratories." ]),
("5.6 Future work", ["The next study should obtain a longitudinal feline clinical cohort with repeated creatinine, BUN, SDMA, USG, proteinuria, weight and timestamps before diagnosis. DAP could support a canine version if access is granted, but it would require a canine title and outcome definition. Morris clinical labs could support a canine design if diagnosis labels and linkage are confirmed. VetCompass, SAVSNET, Banfield or RVC collaboration would be more directly aligned with veterinary clinical prediction than the current public files.", "Methodologically, future work should use temporal or external validation, nested feature selection, calibration updating, decision-curve analysis and human-centred evaluation of explanations. A formal comparison of intrinsic and post-hoc explanation faithfulness should be preregistered before results are inspected." ]),
("5.7 Conclusion", ["This thesis developed and evaluated interpretable machine-learning workflows across two public feline renal cohorts. The clinical cohort supported a small status/stage classification analysis, while the urine-metabolomics cohort supported animal-grouped three-class condition classification. Elastic-net logistic regression, XGBoost and EBM were all implemented, and SHAP, LIME, feature-selection frequency and ablation analyses were used to examine explanatory behaviour.", "The final conclusion is deliberately narrow: interpretable ML is technically feasible for exploratory feline renal classification, but apparent performance depends strongly on the data modality, outcome construction and validation unit. The study does not establish early future-onset CKD detection, clinical utility or deployment readiness. Its principal contribution is a reproducible, transparent benchmark that makes those boundaries visible." ]),
("5.8 Final position", ["The original DAP-based proposal should not be discarded; it should be treated as the prospective next phase. The current thesis is the public-data methodological phase. Once restricted longitudinal data are legitimately available, the pipeline can be extended rather than rewritten: replace binary status with future-onset outcomes, add time-indexed feature engineering, define prediction horizons, calibrate against clinical prevalence, and perform external validation. Until then, the responsible claim is that the present work is a comparative interpretable-classification study, not a clinical early-detection system." ])]: add_unit(doc,h,ps,level=2)

