# Appendices
add_unit(doc, "Appendix A: Frozen dataset manifest", ["The frozen manifest records source article, DOI, URL, local file, sheet, licence, hash, shape, labels, identifiers and scope. It is stored at data/frozen_dataset_manifest.md and is reproduced here as a condensed audit trail.", "Dataset A: 56 rows, 33 columns, 25 Healthy, 31 CKD; no visit dates. Dataset B: 195 rows, 637 columns, 41 IDs in the downloaded file, 97 Healthy, 54 CaOx and 44 CKD; repeated observations grouped by Animal."], table=(['Item','Dataset A','Dataset B'], [['Source','Nealon et al. 2024','Jewell et al. 2025'],['Primary modality','Clinical/laboratory','Urine metabolomics'],['Outcome','Healthy/CKD/stage','Healthy/CaOx/CKD'],['Rows','56','195'],['Animal unit','Patient ID','Animal ID'],['Main limitation','Cross-sectional','High-dimensional and ID discrepancy']], [1.5,2.5,2.5], 'Table A.1. Condensed data audit.'))
add_unit(doc, "Appendix B: Analysis file inventory", ["The analysis outputs directory contains the reproducible metric JSON files, out-of-fold probability tables, explanation rankings, feature-selection frequency table, LIME examples and figures. The central script is analysis/run_analysis.py. The output summary is analysis/outputs/analysis_summary.json.", "The final document reports only values read from the successful final run. Earlier failed runs caused by package compatibility and serialization were corrected and are not used as empirical evidence."], bullets=["clinical_binary_metrics.json", "clinical_context_ablation_metrics.json", "clinical_stage_metrics.json", "metabolomics_metrics.json", "clinical_xgb_shap_importance.csv", "metabolomics_xgb_shap_importance.csv", "metabolomics_feature_selection_frequency.csv", "clinical_roc.png", "clinical_pr.png", "metabolomics_confusion_matrices.png"])
add_unit(doc, "Appendix C: Core pseudocode", ["Input: Dataset A clinical table and Dataset B metabolomics table. Output: fold-safe metrics, explanations and figures.", "1. Load and hash source files. 2. Inspect labels and missingness. 3. Define separate cohort-specific outcomes. 4. For each fold, split animals before imputation and feature selection. 5. Fit elastic-net logistic regression, XGBoost and EBM. 6. Predict held-out animals. 7. Compute AUROC, AUPRC, Brier, accuracy, balanced accuracy and F1. 8. Fit exploratory explainers on the complete cohort with explicit limitations. 9. Save JSON, CSV and PNG outputs. 10. Report results without future-onset claims."], bullets=["Never split repeated observations by row.", "Never fit imputation or feature selection on the evaluation fold.", "Do not call cross-validated internal evaluation external validation.", "Do not call SHAP or LIME causal explanations.", "Do not report full-marker performance without the context-only ablation."])

add_unit(doc, "Appendix D: Clinical data dictionary", ["The clinical workbook contains a compact but clinically rich set of variables. The following dictionary records the intended role of each field and the caution applied during modelling. Variables used in the full-marker model should not be interpreted as independent predictors because several are part of the clinical CKD definition or are downstream consequences of renal dysfunction."], table=(['Variable group','Fields','Role','Primary caution'], [['Identity','Patient ID','Animal key','Not used as a predictor'],['Demography','Age, sex, breed, weight','Context','Small cohort and sampling bias'],['Condition','CKD stage','Outcome','Stage 1 has n=3'],['Renal markers','Creatinine, BUN, SDMA, USG, proteinuria','Full-marker predictors','Definition circularity'],['Systemic markers','Phosphorus, calcium, potassium, sodium, bicarbonate','Physiology','May reflect disease severity'],['Physical state','BCS, MCS, weight loss, fecal score','Context','Measurement and missingness variation'],['Blood measures','HCT, albumin, globulin, TP, cholesterol','Context/systemic','Possible downstream association'],['Other','TT4, diet, medications, antibiotic history','Confounding context','Not all fields used in primary model']], [1.2,2.0,1.7,2.0], 'Table D.1. Clinical variable dictionary.'))
add_unit(doc, "Appendix E: Metabolomics data dictionary", ["Dataset B uses a high-dimensional urine-metabolomics table. The raw spreadsheet contains an animal identifier, a condition label and 635 metabolite columns. The companion legend maps each column identifier to a biochemical name and a PubChem identifier where available. This appendix records the modelling representation and the limitations of treating relative metabolite abundance as a clinical predictor."], table=(['Component','Observed in file','Use in analysis','Limitation'], [['Animal','41 unique IDs','Grouping variable','Paper reports 42 cats'],['Condition','Healthy/CaOx/CKD','Three-class outcome','Not IRIS stage'],['Metabolites','635 named features','Fold-specific feature selection','High dimensionality'],['Rows','195 observations','Input rows','Repeated within animal'],['Legend','635 unique mappings','Explanation labels','Biochemical interpretation not validated'],['Units','Relative/processed values','Model input','Assay-specific scale']], [1.2,1.6,2.1,2.0], 'Table E.1. Metabolomics data dictionary.'))
add_unit(doc, "Appendix F: Mathematical definitions", ["Binary logistic regression was represented as p=σ(β0+βx), where σ is the logistic sigmoid. XGBoost represented an additive ensemble of trees f(x)=ΣkηkTk(x). EBM represented an additive function f(x)=β0+Σifi(xi) without fitted interactions in the main runs. SHAP explanations used additive contributions φi whose sum is linked to the model output under the selected background and output scale.", "AUROC was computed from held-out probabilities and labels. AUPRC was the average precision summary. The binary Brier score was N−1Σi(pi−yi)². Balanced accuracy was the mean of class-specific recall. For multiclass tasks, the Brier score used the squared Euclidean difference between the probability vector and one-hot class vector, averaged across observations. These definitions are included so that the reported metrics are not dependent on software defaults alone."], table=(['Metric','Definition/use','Interpretive caution'], [['AUROC','Ranking discrimination across thresholds','Can look strong with label-defining variables'],['AUPRC','Precision-recall summary','Depends on prevalence'],['Brier','Squared probability error','Lower is better; calibration-sensitive'],['Balanced accuracy','Mean class recall','Useful with class imbalance'],['Macro F1','Unweighted classwise F1 mean','Rare classes remain influential'],['Grouped OOF','Held-out animal predictions','Not external validation']], [1.2,3.0,2.0], 'Table F.1. Metric definitions.'))
add_unit(doc, "Appendix G: Model configurations", ["The configurations were intentionally modest and regularised. They were selected to support a comparison of inductive biases rather than an exhaustive hyperparameter competition. The clinical cohort used repeated stratified five-fold cross-validation with ten repeats. The metabolomics cohort used five-fold StratifiedGroupKFold with animal ID grouping. Feature selection was limited to 40 metabolite features per training fold."], table=(['Model','Key settings','Clinical use','Metabolomics use'], [['Elastic-net logistic','saga; l1_ratio 0.25; C 0.25/0.15; max_iter 5000','Binary and stage','Three-class'],['XGBoost','120 estimators; depth 2; learning rate .04; regularisation','Binary and stage','Three-class'],['EBM','No interactions; max_bins 32/24; outer bags 8/6','Binary','Three-class'],['SHAP','TreeExplainer; mean absolute values','Global XGBoost ranking','Global XGBoost ranking'],['LIME','1000 perturbation samples; three examples','Local illustration','Not primary'],['Feature selection','ANOVA F; k≤40; fit within fold','Not primary','Primary leakage control']], [1.3,3.0,1.4,1.5], 'Table G.1. Configuration summary.'))
add_unit(doc, "Appendix H: TRIPOD+AI and PROBAST+AI mapping", ["The thesis uses reporting and risk-of-bias frameworks as practical checklists. The mapping below records where each major concern appears in the document. The purpose is not to claim compliance with every clinical prediction-model item; several items are not applicable because the study is not a prospective development-and-validation project."], table=(['Domain','Thesis location','Status','Comment'], [['Title/abstract','Cover and Abstract','Addressed','States classification and cohorts'],['Target population','Chapters 1 and 3','Addressed','Cats in two source cohorts'],['Outcome definition','Sections 3.2–3.3','Addressed','Separate cohort-specific outcomes'],['Predictors','Sections 3.5–3.6','Addressed','Feature lists and exclusions'],['Data splitting','Section 3.7','Addressed','Animal grouping for repeated data'],['Model specification','Sections 3.8–3.11','Addressed','Algorithms and explainers stated'],['External validation','Limitations','Not performed','No suitable independent cohort'],['Fairness/subgroups','Future work','Limited','Sample too small for stable subgroup claims'],['Open science','Appendices and manifest','Addressed','Hashes, files, script and outputs']], [1.5,1.7,1.1,2.9], 'Table H.1. Reporting and appraisal mapping.'))
add_unit(doc, "Appendix I: Literature evidence matrix", ["The matrix is a compact audit of why the literature was included. It separates clinical context, veterinary ML, explainability, reporting, ethics and reproducibility. It also prevents the final bibliography from becoming a list without synthesis."], table=(['Source family','Representative sources','Evidence contribution','Use in thesis'], [['Clinical CKD','IRIS; Sparkes; Conroy','Diagnosis, staging, monitoring','Outcome and limitations'],['Feline EHR ML','Biourge; Watson','Early-prediction benchmark','State of art only'],['Feline metabolomics','Nealon; Vanden Broecke; Jewell; Kim','Public cohorts and biomarkers','Dataset and benchmark'],['Veterinary AI','Appleby; Basran; Ezanno; Burti','Translation and access','Gap framing'],['XAI foundations','Lundberg; Ribeiro; Linardatos; Ghassemi','Methods and cautions','Explainability design'],['Tabular modelling','Grinsztajn; Shwartz-Ziv; Borisov','Model choice','XGBoost rationale'],['Reporting','TRIPOD+AI; PROBAST+AI','Transparency and bias','Methods and appraisal'],['Ethics','Morley; Smith; Cohen; Coghlan','Accountability and welfare','Scope boundary'],['Reproducibility','Pineau; McDermott','Code and data transparency','Pipeline controls']], [1.4,2.4,2.0,1.4], 'Table I.1. Literature evidence matrix.'))
add_unit(doc, "Appendix J: Dataset search and access decision log", ["The final study design was selected after screening multiple candidate sources. DAP was not silently dropped: the public repository contains codebooks and survey instruments, while participant-level data require an access pathway. Morris was retained as a future canine route but not used because download required login and CKD outcome linkage was not confirmed. VetCompass was excluded from formal analysis because its open-access terms restrict use to validation and learning exercises. Kaggle datasets were rejected because one explicitly included synthetic expansion and neither matched the clinical CKD outcome.", "The selected sources were the 2024 clinical supplementary workbook and the 2025 PLOS urine-metabolomics raw spreadsheet. They were chosen because they were downloadable, citable, licensed, and sufficiently documented for a reproducible secondary analysis. Their limitations are carried into the title, questions, metrics and conclusion."], table=(['Candidate','Decision','Reason'], [['DAP','Not used','Restricted participant-level data; canine; no credentials'],['Morris labs','Future route','Login required; outcome linkage unconfirmed'],['VetCompass CKD','Not used','Learning/validation terms; download blocked'],['Kaggle clinical','Rejected','Synthetic expansion; no CKD target'],['GEO GSE303653','Secondary only','Omics tissue; not clinical longitudinal'],['2024 clinical workbook','Selected','Public, citable clinical CKD labels'],['2025 urine workbook','Selected','Public raw repeated metabolomics data']], [1.5,1.2,4.1], 'Table J.1. Access decision log.'))

